result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/textdiff.py", "content": """"Word-level diff for grading student translations against a reference."""


def diff(reference_tokens, student_tokens):
    """Compute an LCS-based edit script between two token lists.

    Returns a list of operations:
      ('equal', tokens)
      ('delete', tokens)
      ('insert', tokens)
      ('replace', old_tokens, new_tokens)
    Adjacent delete+insert pairs are merged into a single 'replace'.
    """
    n, m = len(reference_tokens), len(student_tokens)
    # dp[i][j] = LCS length of reference_tokens[i:] and student_tokens[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if reference_tokens[i] == student_tokens[j]:
                dp[i][j] = dp[i + 1][j + 1] + 1
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # Walk the DP table to emit raw operations.
    raw = []  # ('equal'|'delete'|'insert', tokens)
    i = j = 0
    while i < n and j < m:
        if reference_tokens[i] == student_tokens[j]:
            raw.append(("equal", [reference_tokens[i]]))
            i += 1
            j += 1
        elif dp[i + 1][j] >= dp[i][j + 1]:
            raw.append(("delete", [reference_tokens[i]]))
            i += 1
        else:
            raw.append(("insert", [student_tokens[j]]))
            j += 1
    while i < n:
        raw.append(("delete", [reference_tokens[i]]))
        i += 1
    while j < m:
        raw.append(("insert", [student_tokens[j]]))
        j += 1

    # Coalesce runs of the same kind, merging adjacent delete+insert into replace.
    ops = []
    k = 0
    while k < len(raw):
        kind = raw[k][0]
        run = list(raw[k][1])
        k += 1
        while k < len(raw) and raw[k][0] == kind:
            run.extend(raw[k][1])
            k += 1
        if kind == "delete" and k < len(raw) and raw[k][0] == "insert":
            ins = list(raw[k][1])
            k += 1
            while k < len(raw) and raw[k][0] == "insert":
                ins.extend(raw[k][1])
                k += 1
            ops.append(("replace", run, ins))
        else:
            ops.append((kind, run))
    return ops


def lcs_length(reference_tokens, student_tokens):
    """Length of the longest common subsequence."""
    return sum(1 for op in diff(reference_tokens, student_tokens)
               if op[0] == "equal" for _ in op[1])


def similarity(reference_tokens, student_tokens):
    """2 * LCS / (len(ref) + len(stu)); 1.0 for two empty inputs."""
    total = len(reference_tokens) + len(student_tokens)
    if total == 0:
        return 1.0
    return 2.0 * lcs_length(reference_tokens, student_tokens) / total


def render(ops):
    """Render an edit script: deletions as [-word-], insertions as {+word+}."""
    parts = []
    for op in ops:
        if op[0] == "equal":
            parts.extend(op[1])
        elif op[0] == "delete":
            parts.extend("[-%s-]" % w for w in op[1])
        elif op[0] == "insert":
            parts.extend("{+%s+}" % w for w in op[1])
        else:  # replace
            parts.extend("[-%s-]" % w for w in op[1])
            parts.extend("{+%s+}" % w for w in op[2])
    return " ".join(parts)
